item.command:
/bin/bash -lc "printf '%s\\n' '--- fixture files ---'
find \""'$AGMS_RUN/fixture" -maxdepth 4 -type f -print | sort | xargs -I{} stat -f '"'%N %z bytes' {}
printf '%s\\n' '--- product-home files ---'
find \""'$AGMS_RUN/product-home" -maxdepth 3 -type f -print | sort | xargs -I{} stat -f '"'%N %z bytes' {}
printf '%s\\n' '--- timestamp UTC ---'
date -u '+%Y-%m-%dT%H:%M:%SZ'"

